script = r'''
const { readExcel } = require("./tools/excel");
const { llm }       = require("./tools/llm");
const { sendEmail }  = require("./tools/email");

(async () => {
  // 1. Read the Excel file
  const rows = await readExcel("data/order_summary.xlsx");
  console.log("Rows read:", rows.length);
  console.log("Sample row:", JSON.stringify(rows[0]));

  // 2. Build a text representation of the data for the LLM
  const header = Object.keys(rows[0]).join(" | ");
  const body   = rows.map(r => Object.values(r).join(" | ")).join("\n");
  const table  = header + "\n" + body;

  const prompt = `You are a data analyst. Below is order data from a spreadsheet. Please provide a concise executive summary of this data, including total number of orders, any notable trends, top products or categories, and total/average revenue if available.\n\nData:\n${table}`;

  // 3. Summarize with the LLM
  const summary = await llm(prompt);
  console.log("\n=== LLM Summary ===\n" + summary);

  // 4. Email the summary to bob@example.com
  const emailResult = await sendEmail(
    "bob@example.com",
    "Order Summary Report",
    summary
  );
  console.log("\n=== Email Result ===\n" + JSON.stringify(emailResult));
})();
'''

await write_file("./skills/OfficeBench/testbed/run_task.js", script)
